177: template<typename Func>
178: void ScintillaNext::forEachLineInSelection(int selection, Func callback)
179: {
180:     int lineStart = lineFromPosition(selectionNStart(selection));
181:     int lineEnd = lineFromPosition(selectionNEnd(selection));
182: 
183:     for (int curLine = lineStart; curLine <= lineEnd; ++curLine) {
184:         callback(curLine);
185:     }
186: }
187: 
188: // Stick this in the header file...because C++, that's why
189: template<typename Func>
190: void ScintillaNext::forEachMatchInRange(const QByteArray &text, Func callback, Sci_CharacterRange range)
191: {
192:     Sci_TextToFind ttf {range, text.constData(), {-1, -1}};
193:     int flags = searchFlags();
194: 
195:     while (send(SCI_FINDTEXT, flags, reinterpret_cast<sptr_t>(&ttf)) != -1) {
196:         if(ttf.chrgText.cpMin == ttf.chrgText.cpMax)
197:             break;
198:         ttf.chrg.cpMin = callback(ttf.chrgText.cpMin, ttf.chrgText.cpMax);
199:     }
200: }
